    p.write_text(json.dumps(obj, indent=1), encoding="utf-8")


def read_inbox(**_):
    inbox = _load("inbox", [])
    return {"messages": inbox, "count": len(inbox)}


def read_file(path, **_):
    p = _resolve(path)
    if not p.exists():
        return {"error": f"no such file: {path}"}
