"""Billing export.

Row format: "<date>,<amount>". Dates arrive from the upstream system in ISO
8601 (YYYY-MM-DD). The parser previously used "%d-%m-%Y", which rejected every
ISO date and caused the export to fail (incident of 2026-11-08).

Fix: parse ISO 8601. We also accept a few legacy shapes defensively so a single
stray format in a batch does not abort the whole export.
"""

import datetime
import sys

# Accepted input formats, tried in order. ISO first (the current upstream format).
DATE_FORMATS = (
    "%Y-%m-%d",      # 2026-11-08  (current upstream format)
    "%d-%m-%Y",      # 08-11-2026  (legacy)
    "%m/%d/%Y",      # 11/08/2026  (legacy)
    "%Y/%m/%d",      # 2026/11/08
)


def parse_date(text):
    """Parse a billing date string. Raises ValueError if no known format matches."""
    text = text.strip()
    for fmt in DATE_FORMATS:
        try:
            return datetime.datetime.strptime(text, fmt)
        except ValueError:
            continue
    raise ValueError(
        "unrecognised date %r; expected one of: %s" % (text, ", ".join(DATE_FORMATS))
    )


def parse_row(row):
    """Return (date, amount) for a "<date>,<amount>" row."""
    date_text, _, amount_text = row.strip().partition(",")
    if not amount_text:
        raise ValueError("malformed row (no amount): %r" % row)
    return parse_date(date_text), float(amount_text)


def export(rows):
    """Validate and print each row. Returns the parsed (date, amount) list."""
    parsed = []
    for row in rows:
        if not row.strip():
            continue
        day, amount = parse_row(row)
        parsed.append((day, amount))
        print(day.strftime("%Y-%m-%d"), "%.2f" % amount)
    return parsed


def main():
    rows = ["2026-11-08,100.00", "2026-11-07,250.00"]
    try:
        parsed = export(rows)
    except ValueError as exc:
        print("export failed: %s" % exc, file=sys.stderr)
        return 1
    print("exported %d rows, total %.2f" % (len(parsed), sum(a for _, a in parsed)))
    return 0


if __name__ == "__main__":
    sys.exit(main())

